addEventListener('scroll',function(){lookT=[0,.8];lastInput=performance.now()},{passive:true});
var happy=0;document.querySelectorAll('.contact-btn').forEach(function(b){b.addEventListener('pointerenter',function(){happy=1});b.addEventListener('pointerleave',function(){happy=0})});
var visible=true;new IntersectionObserver(function(es){visible=es[0].isIntersecting},{threshold:0}).observe(canvas);
