if(!reduced&&now-lastInput>6000){gx=Math.sin(t*.5)*.7;gy=Math.sin(t*.37)*.25;if(now>nextIdle){poke(.4+Math.random()*.2,.25+Math.random()*.2,(Math.random()-.5)*.8,.4,.1);nextIdle=now+4000+Math.random()*4000}}
if(reduced){gx=0;gy=0}
lookV[0]+=((gx-look[0])*60-lookV[0]*9)*dt;lookV[1]+=((gy-look[1])*60-lookV[1]*9)*dt;look[0]+=lookV[0]*dt;look[1]+=lookV[1]*dt;
